CREATE PROCEDURE "DP_MULTIPLE_FORECAST_DES" (IN TBL_NAME NVARCHAR(100), IN CONTROLTBL_NAME NVARCHAR(100), OUT RESULT TABLE (GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER   AS  BEGIN     DECLARE MULTIPLEFORECAST_CONTROLTBL TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "INTARGS" INT, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR(100));     DECLARE MULTIPLEFORECAST_OUTPARAMETER TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE MULTIPLEFORECAST_RESULT TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE DATA_TABLE TABLE("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE);     DECLARE ROWCNT INT;     DECLARE ROWINDEX INT;     DECLARE GROUPCNT INT;     DECLARE GROUPID VARCHAR (100);          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#SOURCEDATANDGF53J27DJ290DH';     IF ROWCNT>0 THEN         DROP TABLE #SOURCEDATANDGF53J27DJ290DH;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #SOURCEDATANDGF53J27DJ290DH (GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE);     EXECUTE IMMEDIATE 'INSERT INTO #SOURCEDATANDGF53J27DJ290DH SELECT * FROM '||:TBL_NAME;     DATA_TABLE=SELECT * FROM #SOURCEDATANDGF53J27DJ290DH;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#FORECNTRDES';     IF ROWCNT>0 THEN         DROP TABLE #FORECNTRDES;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #FORECNTRDES ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "INTARGS" INT, "DOUBLEARGS" DOUBLE,"STRINGARGS" VARCHAR(100));     EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRDES SELECT * FROM '||:CONTROLTBL_NAME;     MULTIPLEFORECAST_CONTROLTBL=SELECT * FROM #FORECNTRDES;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPGROUPID';     IF ROWCNT>0 THEN         DROP TABLE #TEMPGROUPID;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPGROUPID ("GROUPID" VARCHAR (100));     INSERT INTO #TEMPGROUPID SELECT DISTINCT(GROUPID) as GROUPID FROM :DATA_TABLE;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPUTRESULT';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPUTRESULT;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPUTRESULT ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE);          CALL PALMULTIPLEFORECASTSMOOTHING_PROC(:DATA_TABLE, :MULTIPLEFORECAST_CONTROLTBL, :MULTIPLEFORECAST_OUTPARAMETER, :MULTIPLEFORECAST_RESULT) ;          SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          SELECT COUNT(*) INTO GROUPCNT FROM :DATA_TABLE WHERE GROUPID=:GROUPID;         INSERT INTO #TEMPOUTPUTRESULT SELECT "GROUPID", "TIMESTAMP", CASE WHEN "VALUE"<0 THEN 0 ELSE "VALUE" END AS "VALUE" FROM :MULTIPLEFORECAST_RESULT WHERE GROUPID=:GROUPID AND TIMESTAMP>:GROUPCNT;     END FOR;      RESULT=SELECT * FROM #TEMPOUTPUTRESULT;     SELECT * FROM :MULTIPLEFORECAST_OUTPARAMETER; END
